# Generated by flask-compiler
# routes: display_products, add_product, product_details, delete_product

from flask import Flask, render_template, request, redirect, url_for

app = Flask(__name__)

products = [
    {"id": 1, "name": "Laptop", "price": 1200, "description": "A fast laptop"},
    {"id": 2, "name": "Phone", "price": 800, "description": "A smart phone"},
    {"id": 3, "name": "Headphones", "price": 150, "description": "Noise cancelling"},
]

@app.route("/")
def display_products():
    return render_template("products.html", products=products)


@app.route("/add", methods=["GET", "POST"])
def add_product():
    if request.method == "POST":
        new_id = len(products) + 1
        products.append({
            "id": new_id,
            "name": request.form.get("name"),
            "price": request.form.get("price"),
            "description": request.form.get("description"),
        })
        return redirect(url_for("display_products"))
    return render_template("add_product.html")


@app.route("/product/<int:product_id>")
def product_details(product_id):
    product = products[product_id]
    return render_template("product_details.html", product=product, product_id=product_id)


@app.route("/delete/<int:product_id>", methods=["GET", "POST"])
def delete_product(product_id):
    product = products[product_id]
    if request.method == "POST":
        products.pop(product_id)
        return redirect(url_for("display_products"))
    return render_template("delete_product.html", product=product, product_id=product_id)


if __name__ == "__main__":
    app.run(debug=True)
